def compute(vars):
    total_2013 = vars["v1"]
    total_all_periods = vars["v2"]

    if total_all_periods == 0:
        return None

    percentage = (total_2013 / total_all_periods) * 100

    return {
        "value": percentage,
        "trace": {
            "total_2013": total_2013,
            "total_all_periods": total_all_periods,
            "percentage": percentage,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
